/** 原资金Mapper与新周期Mapper同事务运行，验证开通、来源资格、延期生效及失败回滚。 */
class CoursePrivateTermLifecycleTransactionTest {
    CourseReservedWalletTransactionTest f;
    CoursePrivateTermService service;
    CoursePrivatePlanMapper plans;
    CoursePrivatePlanVersionMapper versions;
    CoursePrivateApplicationMapper applications;
    CoursePrivateContractTermMapper terms;
    CoursePrivateFundingAllocationMapper allocations;
    CoursePrivateTermEventMapper events;
    CoursePrivateTermOrderMapper termOrders;
    CoursePrivateTermSettlementMapper settlements;
    CourseOrderMapper orderRows;
    CoursePlatformMapper products;
    org.springframework.context.annotation.AnnotationConfigApplicationContext pricingContext;
    CoursePrivatePlanRequest config;
    ObjectMapper json=new ObjectMapper().findAndRegisterModules();
    MutableClock clock=new MutableClock(Instant.parse("2026-10-14T02:00:00Z"));
    @BeforeEach void setup() throws Exception {
        f=new CourseReservedWalletTransactionTest();f.clock=clock;f.setup();
        // 仅清理本夹具尚无资金和历史的初始空关系，模拟第一次申请，不对生产钱包执行删除。
        f.jdbc.update("DELETE FROM course_reserved_wallet WHERE id=5");f.jdbc.update("DELETE FROM course_private_contract WHERE id=3");
        var configuration=new MybatisConfiguration();configuration.setMapUnderscoreToCamelCase(true);
        for(var mapper:List.of(CoursePrivatePlanMapper.class,CoursePrivatePlanVersionMapper.class,CoursePrivateApplicationMapper.class,CoursePrivateContractTermMapper.class,CoursePrivateFundingAllocationMapper.class,CoursePrivateTermEventMapper.class,CoursePrivateTermOrderMapper.class,CoursePrivateTermSettlementMapper.class,CourseOrderMapper.class))configuration.addMapper(mapper);
        var factory=new MybatisSqlSessionFactoryBean();factory.setDataSource(f.jdbc.getDataSource());factory.setConfiguration(configuration);var session=new SqlSessionTemplate(factory.getObject());
        for(var entity:List.of(CoursePrivatePlan.class,CoursePrivatePlanVersion.class,CoursePrivateApplication.class,CoursePrivateContractTerm.class,CoursePrivateFundingAllocation.class,CoursePrivateTermEvent.class,CoursePrivateTermOrder.class,CoursePrivateTermSettlement.class,CourseOrder.class))table(entity);
        f.jdbc.execute("CREATE UNIQUE INDEX term_number ON course_private_contract_term(contract_id,term_no)");f.jdbc.execute("CREATE UNIQUE INDEX next_source ON course_private_contract_term(renewal_source_term_id)");f.jdbc.execute("CREATE UNIQUE INDEX funds_once ON course_private_funding_allocation(ledger_id)");f.jdbc.execute("CREATE UNIQUE INDEX event_once ON course_private_term_event(biz_no)");f.jdbc.execute("CREATE UNIQUE INDEX order_once ON course_private_term_order(order_id)");
        f.jdbc.execute("CREATE UNIQUE INDEX settlement_revision ON course_private_term_settlement(term_id,revision_no)");f.jdbc.execute("CREATE UNIQUE INDEX settlement_identity ON course_private_term_settlement(term_id,operation_fingerprint)");settlements=session.getMapper(CoursePrivateTermSettlementMapper.class);
        plans=session.getMapper(CoursePrivatePlanMapper.class);versions=session.getMapper(CoursePrivatePlanVersionMapper.class);applications=session.getMapper(CoursePrivateApplicationMapper.class);terms=session.getMapper(CoursePrivateContractTermMapper.class);allocations=session.getMapper(CoursePrivateFundingAllocationMapper.class);events=session.getMapper(CoursePrivateTermEventMapper.class);termOrders=session.getMapper(CoursePrivateTermOrderMapper.class);
        orderRows=session.getMapper(CourseOrderMapper.class);products=mock(CoursePlatformMapper.class);var product=new CoursePlatform();product.setId(9L);product.setStatus(1);product.setIsSelfOperated(0);when(products.selectById(9L)).thenReturn(product);when(products.selectByIdForUpdate(9L)).thenReturn(product);
        var authority=mock(UserAuthorityMapper.class);when(authority.findAuthoritiesByUserId(8L)).thenReturn(List.of("course-private-contract:review"));
        var target=new CoursePrivateTermService(f.users,products,mock(PlatformCategoryMapper.class),f.contracts,f.wallets,plans,versions,applications,terms,allocations,events,termOrders,new CoursePrivateOperationsAccess(f.users,authority),json,new CoursePrivateOperationsTime(clock));
        org.springframework.test.util.ReflectionTestUtils.setField(target,"enabled",true);var proxy=new ProxyFactory(target);proxy.addAdvice(new TransactionInterceptor(f.tx.getTransactionManager(),new AnnotationTransactionAttributeSource()));service=(CoursePrivateTermService)proxy.getProxy();
        org.springframework.test.util.ReflectionTestUtils.setField(f.service,"privateTerms",service);
        config=new CoursePrivatePlanRequest();config.setPlatformId(9L);config.setPlanCode("TIME30");config.setPlanName("三十天预存");config.setReason("测试开通");config.setVisibleToAgents(true);
        var rules=new CoursePrivatePlanRules();rules.setMode("TIME_PREPAID");rules.setFixedPrice(new BigDecimal("7.20"));rules.setInitialDepositAmount(new BigDecimal("100"));rules.setValidityDays(30);config.setRules(rules);seed();
    }
    void table(Class<?> type){var info=TableInfoHelper.getTableInfo(type);var columns=new ArrayList<String>();columns.add(info.getKeyColumn()+" BIGINT AUTO_INCREMENT PRIMARY KEY");for(var field:info.getFieldList()){var javaType=field.getPropertyType();String sqlType=javaType==Long.class?"BIGINT":javaType==Integer.class?"INT":javaType==Boolean.class?"BOOLEAN":javaType==BigDecimal.class?"DECIMAL(30,2)":javaType==LocalDateTime.class?"TIMESTAMP":"VARCHAR(16384)";columns.add(field.getColumn()+" "+sqlType+(field.getColumn().equals("is_deleted")?" DEFAULT 0":""));}f.jdbc.execute("CREATE TABLE "+info.getTableName()+"("+String.join(",",columns)+")");}
    void seed() throws Exception {
        f.jdbc.update("DELETE FROM course_private_plan_version");f.jdbc.update("DELETE FROM course_private_plan");f.jdbc.update("DELETE FROM course_private_application");
        var plan=new CoursePrivatePlan();plan.setId(1L);plan.setPlatformId(9L);plan.setPlanCode(config.getPlanCode());plan.setPlanName(config.getPlanName());plan.setMode(config.getRules().getMode());plan.setApplicationMode(config.getApplicationMode());plan.setVisibleToAgents(true);plan.setStatus("PUBLISHED");plan.setCurrentVersionId(1L);plan.setDraftVersion(1);plans.insert(plan);
        var version=new CoursePrivatePlanVersion();org.springframework.beans.BeanUtils.copyProperties(config.getRules(),version);version.setId(1L);version.setPlanId(1L);version.setPlatformId(9L);version.setVersionNo(1);version.setPublishedAt(LocalDateTime.now(clock).minusDays(1));version.setCostVersionId(1L);version.setConfigSnapshot(json.writeValueAsString(config));versions.insert(version);
        var app=new CoursePrivateApplication();app.setId(1L);app.setSubmittedBy(7L);app.setUserId(7L);app.setPlatformId(9L);app.setPlanId(1L);app.setVersionId(1L);app.setApplicationType("OPEN");app.setEffectivePolicy("NEXT_TERM");app.setAcknowledgeLegacyChange(false);app.setStatus("PENDING");app.setRequestKey("test_open");app.setOperationFingerprint("0".repeat(64));app.setVersion(0);app.setSubmittedAt(LocalDateTime.now(clock));applications.insert(app);
    }
    @AfterEach void clear(){if(pricingContext!=null)pricingContext.close();f.cleanup();}
    void auth(long id){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,id==8?List.of(new SimpleGrantedAuthority("course-private-contract:review"),new SimpleGrantedAuthority("course-wallet:release")):List.of()));}
    CoursePrivateContractTerm enroll(){auth(8);return service.enroll(1L,0,8L,"审核开通");}
    CourseReservedWallet wallet(){return f.wallets.selectByBinding(7L,9L);}
    void deposit(String amount,String key){auth(7);f.tx.executeWithoutResult(tx->f.service.transferIn(wallet().getId(),7L,f.request(amount,key)));}
    CoursePrivateContractTerm current(){return terms.selectById(f.contracts.selectByBinding(7L,9L).getCurrentTermId());}
    com.course.platform.application.service.order.CourseOrderService orderService(){
        pricingContext=new org.springframework.context.annotation.AnnotationConfigApplicationContext();pricingContext.registerBean(CoursePrivateRenewalService.class,()->mock(CoursePrivateRenewalService.class));pricingContext.registerBean(CoursePrivateUpgradeService.class,()->mock(CoursePrivateUpgradeService.class));pricingContext.registerBean(CoursePrivateSettlementService.class,()->mock(CoursePrivateSettlementService.class));pricingContext.registerBean(CoursePrivateTermService.class,()->service);pricingContext.registerBean(CoursePricingService.class,()->new CoursePricingService(f.users,products,mock(PlatformCategoryMapper.class),f.contracts,f.wallets,clock));pricingContext.refresh();
        var general=(AccountLedgerServiceImpl)org.springframework.test.util.ReflectionTestUtils.getField(f.service,"generalLedger");
        var target=new CourseOrderServiceImpl(orderRows,products,f.users,mock(com.course.platform.application.service.support.OperationLogService.class),mock(com.course.platform.application.service.platform.PlatformDockingService.class),mock(ApiProviderMapper.class),mock(org.springframework.context.ApplicationEventPublisher.class),general,new com.course.platform.security.ResourceAuthorizationService(),mock(com.course.platform.application.service.order.CourseOrderProgressLogService.class),pricingContext.getBean(CoursePricingService.class),f.service,new CourseOrderPaymentService(general,f.service,orderRows));
        var proxy=new ProxyFactory(target);proxy.addAdvice(new TransactionInterceptor(f.tx.getTransactionManager(),new AnnotationTransactionAttributeSource()));return (com.course.platform.application.service.order.CourseOrderService)proxy.getProxy();
    }
    OrderCreateRequest orderRequest(String key){var request=new OrderCreateRequest();request.setPlatformId(9L);request.setStudentAccount("student_"+key);request.setStudentPassword("测试口令");request.setCourseName("测试课程");request.setCourseId("opaque_"+key);request.setClientRequestId(key);return request;}
    @Test void oneConfirmedScheduledQuoteSupportsBatchAndLostResponseAfterActivation() throws Exception {config.getRules().setActivationFrom(LocalDateTime.now(clock).plusDays(2));seed();enroll();deposit("100","batch_start");clock.advance(Duration.ofDays(2));var orders=orderService();var pricing=pricingContext.getBean(CoursePricingService.class);var quote=pricing.preview(7L,9L);var first=orderRequest("batch_first");first.setExpectedAmount(quote.finalPrice());first.setExpectedContractVersion(quote.contractVersion());first.setExpectedPriceSource("PRIVATE");first.setExpectedPaymentSource("COURSE_WALLET");first.setExpectedPolicyTermId(quote.privateTermId());first.setExpectedPolicyVersionId(quote.privatePlanVersionId());first.setExpectedPolicyExpiresAt(quote.expiresAt());Long id=orders.createOrder(first,7L);var second=orderRequest("batch_second");org.springframework.beans.BeanUtils.copyProperties(first,second,"clientRequestId","studentAccount","courseId");orders.createOrder(second,7L);f.money("85.60",wallet().getBalance());first.setExpectedContractVersion(f.contracts.selectByBinding(7L,9L).getVersion());assertEquals(id,orders.createOrder(first,7L));f.money("85.60",wallet().getBalance());}
    @Test void approvalCreatesOnePendingTermAndOneOriginalWalletWithoutCharging(){var term=enroll();assertEquals("PENDING_ACTIVATION",term.getStatus());assertNull(term.getStartAt());assertEquals("APPROVED",applications.selectById(1L).getStatus());f.money("500",f.balance("sys_user",7));f.money("0",wallet().getBalance());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_reserved_wallet_ledger",Integer.class));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void firstDepositActivatesFromRealQualificationAndFreezesThirtyDays(){enroll();clock.advance(Duration.ofHours(2));deposit("40","a");assertEquals("PENDING_ACTIVATION",current().getStatus());clock.advance(Duration.ofHours(1));deposit("60","b");var term=current();assertEquals("ACTIVE",term.getStatus());assertEquals(LocalDateTime.now(clock),term.getStartAt());assertEquals(term.getStartAt().plusDays(30),term.getEndAt());assertEquals(term.getEndAt().plusDays(7),term.getSettlementDeadlineAt());assertEquals(2,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));f.money("100",term.getQualifiedDepositAmount());f.money("400",f.balance("sys_user",7));}
    @Test void zeroThresholdPermanentTermHasNoArtificialExpiration() throws Exception {config.getRules().setMode("PERMANENT_PREPAID");config.getRules().setValidityDays(null);config.getRules().setInitialDepositAmount(BigDecimal.ZERO);seed();var term=enroll();assertEquals("ACTIVE",term.getStatus());assertNull(term.getEndAt());assertNull(term.getSettlementDeadlineAt());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));}
    @Test void delayedActivationDoesNotSpendWaitingDaysAndPromotesUnderLocks() throws Exception {config.getRules().setActivationFrom(LocalDateTime.now(clock).plusDays(2));seed();enroll();deposit("100","a");assertEquals("SCHEDULED",current().getStatus());assertNull(service.effectiveTerm(7L,9L,false));clock.advance(Duration.ofDays(2));f.tx.executeWithoutResult(tx->assertEquals("ACTIVE",service.effectiveTerm(7L,9L,true).getStatus()));assertEquals(LocalDateTime.now(clock).plusDays(30),current().getEndAt());}
    @Test void releasedMoneyBeforeStartCannotKeepScheduledQualification() throws Exception {config.getRules().setActivationFrom(LocalDateTime.now(clock).plusDays(2));seed();enroll();deposit("100","a");auth(8);f.tx.executeWithoutResult(tx->f.service.release(wallet().getId(),8L,f.request("50","out")));clock.advance(Duration.ofDays(2));assertNull(service.effectiveTerm(7L,9L,false));f.tx.executeWithoutResult(tx->assertNull(service.effectiveTerm(7L,9L,true)));clock.advance(Duration.ofHours(3));deposit("50","b");assertEquals(LocalDateTime.now(clock),current().getStartAt());assertEquals("ACTIVE",current().getStatus());}
    @Test void approvalRetryAndConcurrencyReturnOneTerm() throws Exception {Runnable action=()->{auth(8);try{service.enroll(1L,0,8L,"审核开通");}finally{SecurityContextHolder.clearContext();}};var results=f.concurrent(action,action);assertEquals(0,results.stream().filter(RuntimeException.class::isInstance).count());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_term_event WHERE biz_no='application_1_approve'",Integer.class));}
    @Test void failureToSaveApprovalRollsBackNewContractWalletAndTerm(){f.jdbc.execute("ALTER TABLE course_private_application ADD CONSTRAINT reject_approve CHECK(status<>'APPROVED')");assertThrows(RuntimeException.class,this::enroll);assertNull(f.contracts.selectByBinding(7L,9L));assertNull(f.wallets.selectByBinding(7L,9L));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));assertEquals("PENDING",applications.selectById(1L).getStatus());}
    @Test void failedQualificationAllocationRollsBackDepositAndBothLedgers(){enroll();f.jdbc.execute("ALTER TABLE course_private_funding_allocation ADD CONSTRAINT reject_fund CHECK(amount<100)");assertThrows(RuntimeException.class,()->deposit("100","a"));f.money("500",f.balance("sys_user",7));f.money("0",wallet().getBalance());assertEquals("PENDING_ACTIVATION",current().getStatus());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM account_ledger",Integer.class));}
    @Test void staleApplicationVersionAndForgedOperatorCannotApprove(){auth(8);assertThrows(BusinessException.class,()->service.enroll(1L,9,8L,"审核"));assertThrows(BusinessException.class,()->service.enroll(1L,0,7L,"审核"));assertNull(f.contracts.selectByBinding(7L,9L));}
    @Test void modernPaidOrderFreezesExactTermAndOneAssociation(){enroll();deposit("100","a");var orders=orderService();auth(7);Long id=orders.createOrder(orderRequest("buy"),7L);var order=orderRows.selectById(id);assertEquals(current().getId(),order.getPrivateTermId());assertEquals(current().getVersionId(),order.getPrivatePlanVersionId());assertEquals("TIME_PREPAID",order.getPrivateOperationsMode());assertEquals(current().getVersion(),order.getPrivateTermVersion());assertEquals(current().getId(),termOrders.selectByOrderId(id).getTermId());f.money("92.80",wallet().getBalance());assertEquals(id,orders.createOrder(orderRequest("buy"),7L));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_term_order",Integer.class));}
    @Test void termAssociationFailureRollsBackOriginalWalletDebitAndInsertedOrder(){enroll();deposit("100","a");var orders=orderService();f.jdbc.execute("ALTER TABLE course_private_term_order ADD CONSTRAINT reject_association CHECK(ordered_amount<7)");auth(7);assertThrows(RuntimeException.class,()->orders.createOrder(orderRequest("buy"),7L));f.money("100",wallet().getBalance());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_order",Integer.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_reserved_wallet_ledger WHERE biz_type='ORDER'",Integer.class));}
    @Test void scheduledQualificationMaterializationAcceptsUnchangedFrozenQuoteRatherThanEndlessRollback() throws Exception {config.getRules().setActivationFrom(LocalDateTime.now(clock).plusDays(2));seed();enroll();deposit("100","a");Integer confirmedVersion=f.contracts.selectByBinding(7L,9L).getVersion();clock.advance(Duration.ofDays(2));var orders=orderService();auth(7);var request=orderRequest("scheduled_buy");request.setExpectedContractVersion(confirmedVersion);request.setExpectedAmount(new BigDecimal("7.20"));request.setExpectedPaymentSource("COURSE_WALLET");Long id=orders.createOrder(request,7L);assertEquals(current().getId(),orderRows.selectById(id).getPrivateTermId());assertEquals("ACTIVE",current().getStatus());assertEquals(confirmedVersion+1,orderRows.selectById(id).getContractVersion());f.money("92.80",wallet().getBalance());}
    @Test void settlementGraceDoesNotPermitNewPurchase(){enroll();deposit("100","a");var orders=orderService();clock.advance(Duration.ofDays(30));auth(7);assertThrows(BusinessException.class,()->orders.createOrder(orderRequest("expired_buy"),7L));f.money("100",wallet().getBalance());f.money("400",f.balance("sys_user",7));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_order",Integer.class));}
    @Test void modernChargeWithoutTermSnapshotFailsBeforeWalletDebit(){enroll();deposit("100","a");var contract=f.contracts.selectByBinding(7L,9L);var order=new CourseOrder();order.setId(123L);order.setUserId(7L);order.setPlatformId(9L);order.setOrderNo("forged_legacy_shape");order.setAmount(new BigDecimal("7.20"));order.setPrivateContractId(contract.getId());order.setWalletId(wallet().getId());order.setContractVersion(contract.getVersion());order.setPriceSource("PRIVATE");order.setPaymentSource("COURSE_WALLET");assertThrows(BusinessException.class,()->f.tx.executeWithoutResult(tx->f.service.charge(order)));f.money("100",wallet().getBalance());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_reserved_wallet_ledger WHERE biz_type='ORDER'",Integer.class));}
    @Test void genericOrderUpdateCannotRewriteTermSnapshots(){enroll();deposit("100","a");var orders=orderService();auth(7);Long id=orders.createOrder(orderRequest("immutable"),7L);var before=orderRows.selectById(id);var changed=new CourseOrder();changed.setId(id);changed.setPrivateTermId(999L);changed.setPrivateTermVersion(99);changed.setPrivatePlanVersionId(999L);changed.setPrivateOperationsMode("PERMANENT_PREPAID");changed.setFulfilledAt(LocalDateTime.now(clock));changed.setFulfillmentSource("client_forgery");changed.setOrderStatus(1);orderRows.updateById(changed);var actual=orderRows.selectById(id);assertEquals(before.getPrivateTermId(),actual.getPrivateTermId());assertEquals(before.getPrivateTermVersion(),actual.getPrivateTermVersion());assertEquals(before.getPrivatePlanVersionId(),actual.getPrivatePlanVersionId());assertEquals(before.getPrivateOperationsMode(),actual.getPrivateOperationsMode());assertNull(actual.getFulfilledAt());assertNull(actual.getFulfillmentSource());}
    @Test void automaticEnrollmentRequiresPublishedPublicAutoPolicy() throws Exception {auth(7);assertThrows(BusinessException.class,()->service.enrollAutomatic(1L,7L));config.setApplicationMode("AUTO");seed();var term=service.enrollAutomatic(1L,7L);assertEquals("PENDING_ACTIVATION",term.getStatus());assertEquals(7L,applications.selectById(1L).getReviewedBy());}
    @Test void reviewedRejoinReusesOriginalWalletAndExcludesPriorSameSecondFunding(){var first=enroll();deposit("100","a");Long walletId=wallet().getId();Long contractId=first.getContractId();f.jdbc.update("UPDATE course_private_contract SET status='TERMINATED' WHERE id=?",contractId);f.jdbc.update("UPDATE course_private_contract_term SET status='TERMINATED',superseded_at=? WHERE id=?",LocalDateTime.now(clock),first.getId());var app=applications.selectById(1L);app.setId(2L);app.setRequestKey("rejoin");app.setApplicationType("REJOIN");app.setContractId(contractId);app.setStatus("PENDING");app.setVersion(0);app.setAcknowledgeLegacyChange(true);app.setReviewedBy(null);app.setReviewedAt(null);applications.insert(app);auth(8);var next=service.enroll(2L,0,8L,"已确认重新签约");assertEquals(walletId,wallet().getId());assertEquals(contractId,next.getContractId());assertEquals(2,next.getRelationGeneration());assertEquals("PENDING_ACTIVATION",next.getStatus());f.money("100",wallet().getBalance());deposit("100","b");assertEquals("ACTIVE",current().getStatus());assertEquals(2,f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));assertEquals("TERMINATED",terms.selectById(first.getId()).getStatus());f.money("200",wallet().getBalance());}
    static class MutableClock extends Clock {private volatile Instant instant;MutableClock(Instant value){instant=value;}void advance(Duration duration){instant=instant.plus(duration);}@Override public ZoneId getZone(){return ZoneId.of("Asia/Shanghai");}@Override public Clock withZone(ZoneId zone){return Clock.fixed(instant,zone);}@Override public Instant instant(){return instant;}}
}
